def evolved_p91(x, N, rank, world_size, num_devices,
                 cores_per_device, xm, torch, num_nodes=1):
    # x[i,j] = (-1)^(i+j) = (-1)^i * (-1)^j  -> outer product of sign vector
    v = 1 - 2 * (torch.arange(N, device=x.device) % 2)
    return (v.view(N, 1) * v.view(1, N)).to(x.dtype)

def evolved_p91(x, N, rank, world_size, num_devices,
                 cores_per_device, xm, torch, num_nodes=1):
    # x[i,j] = (-1)^(i+j) = outer product of (-1)^i sign vector
    v = 1 - 2 * (torch.arange(N, device=x.device, dtype=x.dtype) % 2)
    return v.view(N, 1) * v.view(1, N)
